window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7fd1432ae95405a8"]={"versions": [{"id": "FIG-7fd1432ae95405a8", "releases": ["R19-03", "R19-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd FunctionGroup State transition</code>) im Kontext der AUTOSAR Adaptive Platform (SWS State Management). Das Diagramm spezifiziert die Interaktion zur Zustandsüberführung einer Funktionsgruppe (<code>FunctionGroup</code>) ausgelöst durch einen externen Trigger.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Hauptkomponenten bzw. Entitäten sowie deren Interaktionspunkte:</p>\n<ul class=\"fig-list\"><li><code>Application1</code>: Externe adaptive Anwendung, sendet Schreibbefehle.\n</li><li><code>State Management</code>: Zentrale funktionale Einheit mit den Interaktionspunkten <code>TriggerIn</code> (Eingangs-Port) und <code>TriggerOut</code> (Ausgangs-Port) sowie der internen Logik-Lebenslinie.\n</li><li><code>Execution Management</code>: Plattform-Komponente zur Prozess- und Zustandssteuerung mit den Schnittstellen-Ports <code>IFC GetState</code> und <code>IFC Request State</code> inklusive zugehöriger interner Ausführungslinien.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Application1</code> initiiert den Vorgang durch den Aufruf <code>write()</code> an den Port <code>TriggerIn</code>.\n</li><li><code>TriggerIn</code> leitet den Trigger mittels <code>event()</code> an die Hauptlebenslinie von <code>State Management</code> weiter.\n</li><li><code>State Management</code> evaluiert intern die Bedingungen über den Selbstaufruf <code>checkGuardCondition(s)</code>.\n</li><li><code>State Management</code> meldet den Vorzustand über <code>write(pre_state)</code> an <code>TriggerOut</code>.\n</li><li><code>State Management</code> fordert über die Schnittstelle <code>IFC Request State</code> den Zustandswechsel mittels <code>SetState()</code> an.\n</li><li>Innerhalb von <code>Execution Management</code> wird die Zustandsänderung asynchron/synchron verarbeitet und <code>set FunctionGroupState()</code> ausgeführt.\n</li><li><code>State Management</code> fragt über <code>IFC GetState</code> den aktuellen Zustand per <code>GetState()</code> ab.\n</li><li>Nach Bestätigung meldet <code>State Management</code> den Endzustand über <code>write(final_state)</code> an <code>TriggerOut</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz zeigt das Interaktionsmuster zur Funktionsgruppen-Zustandsumschaltung. Für Integratoren und Entwickler definiert das Diagramm die Pflicht zur Absicherung über Guard-Conditions, die zweistufige Zustandsmeldung (<code>pre_state</code> und <code>final_state</code>) über TriggerOut sowie die Verwendung der Execution-Management-Schnittstellen <code>IFC Request State</code> (<code>SetState</code>) und <code>IFC GetState</code> (<code>GetState</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-97a4adde484aa03c", "releases": ["R20-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd FunctionGroup State transition</code>) im Kontext der AUTOSAR Adaptive Platform (SWS State Management). Das Diagramm spezifiziert die Interaktion zur Zustandsüberführung einer Funktionsgruppe (<code>FunctionGroup</code>) ausgelöst durch einen externen Trigger.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Hauptkomponenten bzw. Entitäten sowie deren Interaktionspunkte:</p>\n<ul class=\"fig-list\"><li><code>Application1</code>: Externe adaptive Anwendung, sendet Schreibbefehle.\n</li><li><code>State Management</code>: Zentrale funktionale Einheit mit den Interaktionspunkten <code>TriggerIn</code> (Eingangs-Port) und <code>TriggerOut</code> (Ausgangs-Port) sowie der internen Logik-Lebenslinie.\n</li><li><code>Execution Management</code>: Plattform-Komponente zur Prozess- und Zustandssteuerung mit den Schnittstellen-Ports <code>IFC GetState</code> und <code>IFC Request State</code> inklusive zugehöriger interner Ausführungslinien.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Application1</code> initiiert den Vorgang durch den Aufruf <code>write()</code> an den Port <code>TriggerIn</code>.\n</li><li><code>TriggerIn</code> leitet den Trigger mittels <code>event()</code> an die Hauptlebenslinie von <code>State Management</code> weiter.\n</li><li><code>State Management</code> evaluiert intern die Bedingungen über den Selbstaufruf <code>checkGuardCondition(s)</code>.\n</li><li><code>State Management</code> meldet den Vorzustand über <code>write(pre_state)</code> an <code>TriggerOut</code>.\n</li><li><code>State Management</code> fordert über die Schnittstelle <code>IFC Request State</code> den Zustandswechsel mittels <code>SetState()</code> an.\n</li><li>Innerhalb von <code>Execution Management</code> wird die Zustandsänderung asynchron/synchron verarbeitet und <code>set FunctionGroupState()</code> ausgeführt.\n</li><li><code>State Management</code> fragt über <code>IFC GetState</code> den aktuellen Zustand per <code>GetState()</code> ab.\n</li><li>Nach Bestätigung meldet <code>State Management</code> den Endzustand über <code>write(final_state)</code> an <code>TriggerOut</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz zeigt das Interaktionsmuster zur Funktionsgruppen-Zustandsumschaltung. Für Integratoren und Entwickler definiert das Diagramm die Pflicht zur Absicherung über Guard-Conditions, die zweistufige Zustandsmeldung (<code>pre_state</code> und <code>final_state</code>) über TriggerOut sowie die Verwendung der Execution-Management-Schnittstellen <code>IFC Request State</code> (<code>SetState</code>) und <code>IFC GetState</code> (<code>GetState</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f58aee2d992670e0", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd FunctionGroup State transition</code>) im Kontext der AUTOSAR Adaptive Platform (SWS State Management). Das Diagramm spezifiziert die Interaktion zur Zustandsüberführung einer Funktionsgruppe (<code>FunctionGroup</code>) ausgelöst durch einen externen Trigger.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Entitäten sowie deren Interaktionspunkte:</p>\n<ul class=\"fig-list\"><li><code>Process1</code>: Ausführende Entität bzw. Prozess, agiert als Trigger-Quelle.\n</li><li><code>State Management</code>: Zentrale funktionale Einheit mit den Interaktionspunkten <code>TriggerIn</code> (Eingangs-Port) und <code>TriggerOut</code> (Ausgangs-Port) sowie der zentralen Lebenslinie.\n</li><li><code>Execution Management</code>: Plattform-Komponente zur Prozesssteuerung mit dem Port <code>IFC Requ...</code> (<code>IFC Request State</code>) und zugehörigen Ausführungslinien; ein Port für <code>GetState</code> ist nicht vorhanden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Process1</code> initiiert die Sequenz durch <code>write()</code> an den Port <code>TriggerIn</code>.\n</li><li><code>TriggerIn</code> übergibt die Anforderung via <code>event()</code> an <code>State Management</code>.\n</li><li><code>State Management</code> prüft intern die Übergangsbedingungen mittels <code>checkGuardCondition(s)</code>.\n</li><li><code>State Management</code> signalisiert den Vorbereitungszustand über <code>write(pre_state)</code> an den Port <code>TriggerOut</code>.\n</li><li><code>State Management</code> initiiert den Zustandswechsel über den Aufruf <code>SetState()</code> an den Port <code>IFC Requ...</code> von <code>Execution Management</code>.\n</li><li><code>Execution Management</code> führt intern <code>set FunctionGroupState()</code> aus und meldet den Abschluss an die aufrufende Sequenz zurück.\n</li><li><code>State Management</code> signalisiert den finalen Zustand über <code>write(final_state)</code> an <code>TriggerOut</code>. Eine explizite Abfrage über <code>GetState()</code> entfällt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz dokumentiert die Reduktion der Interaktion zwischen State Management und Execution Management auf die Anforderungsschnittstelle <code>IFC Request State</code>. Das Abfragen des Zustands über einen gesonderten <code>GetState()</code>-Aufruf vor Meldung des <code>final_state</code> ist entfallen; die erfolgreiche Rückkehr oder Benachrichtigung von <code>SetState()</code> schließt die Ausführung von <code>set FunctionGroupState()</code> ab. Anwendungsseitig wird der aufrufende Kontext nun als <code>Process1</code> modelliert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9d2b478306ce8ca0", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd FunctionGroup State transition</code>) im Kontext der AUTOSAR Adaptive Platform (SWS State Management). Das Diagramm spezifiziert die Interaktion zur Zustandsüberführung einer Funktionsgruppe (<code>FunctionGroup</code>) ausgelöst durch einen externen Trigger.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Entitäten sowie deren Interaktionspunkte:</p>\n<ul class=\"fig-list\"><li><code>Process1</code>: Ausführende Entität bzw. Prozess, agiert als Trigger-Quelle.\n</li><li><code>State Management</code>: Zentrale funktionale Einheit mit den Interaktionspunkten <code>TriggerIn</code> (Eingangs-Port) und <code>TriggerOut</code> (Ausgangs-Port) sowie der zentralen Lebenslinie.\n</li><li><code>Execution Management</code>: Plattform-Komponente zur Prozesssteuerung mit dem Port <code>IFC Requ...</code> (<code>IFC Request State</code>) und zugehörigen Ausführungslinien; ein Port für <code>GetState</code> ist nicht vorhanden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Process1</code> initiiert die Sequenz durch <code>write()</code> an den Port <code>TriggerIn</code>.\n</li><li><code>TriggerIn</code> übergibt die Anforderung via <code>event()</code> an <code>State Management</code>.\n</li><li><code>State Management</code> prüft intern die Übergangsbedingungen mittels <code>checkGuardCondition(s)</code>.\n</li><li><code>State Management</code> signalisiert den Vorbereitungszustand über <code>write(pre_state)</code> an den Port <code>TriggerOut</code>.\n</li><li><code>State Management</code> initiiert den Zustandswechsel über den Aufruf <code>SetState()</code> an den Port <code>IFC Requ...</code> von <code>Execution Management</code>.\n</li><li><code>Execution Management</code> führt intern <code>set FunctionGroupState()</code> aus und meldet den Abschluss an die aufrufende Sequenz zurück.\n</li><li><code>State Management</code> signalisiert den finalen Zustand über <code>write(final_state)</code> an <code>TriggerOut</code>. Eine explizite Abfrage über <code>GetState()</code> entfällt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz dokumentiert die Reduktion der Interaktion zwischen State Management und Execution Management auf die Anforderungsschnittstelle <code>IFC Request State</code>. Das Abfragen des Zustands über einen gesonderten <code>GetState()</code>-Aufruf vor Meldung des <code>final_state</code> ist entfallen; die erfolgreiche Rückkehr oder Benachrichtigung von <code>SetState()</code> schließt die Ausführung von <code>set FunctionGroupState()</code> ab. Anwendungsseitig wird der aufrufende Kontext nun als <code>Process1</code> modelliert.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7fd1432ae95405a8", "to": "FIG-97a4adde484aa03c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-97a4adde484aa03c", "to": "FIG-7fd1432ae95405a8", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-97a4adde484aa03c", "to": "FIG-f58aee2d992670e0", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Lebenslinie <code>Application1</code> wurde in <code>Process1</code> umbenannt.\n</li><li>Der Port bzw. das Interface <code>IFC GetState</code> bei <code>Execution Management</code> sowie die zugehörige Lebenslinie wurden entfernt.\n</li><li>Der synchrone/asynchrone Aufruf <code>GetState()</code> von <code>State Management</code> an <code>IFC GetState</code> entfällt vollständig.\n</li><li>Der Port <code>IFC Request State</code> ist auf <code>IFC Requ...</code> verkürzt dargestellt.\n</li></ul>"}, {"from": "FIG-f58aee2d992670e0", "to": "FIG-9d2b478306ce8ca0", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
